    [MethodImpl((MethodImplOptions)256)]
    public bool Equals(K x, K y) => ReferenceEquals(x, y) || x.Equals(y);

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public int GetHashCode(K key) => key.GetHashCode();
}

/// <summary>Uses the integer itself as hash code and `==` for equality</summary>
public struct IntEq : IEq<int>
{
    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public int GetTombstone() => int.MinValue; // todo: @improve separate the tombstone from the hash

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public bool Equals(int x, int y) => x == y;

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public int GetHashCode(int key) => key;
}

/// <summary>General tools for IEq and its implementations</summary>
public static class Eq
{
    /// <summary>Factor to multiple by, to achieve the Fibonacci hashing (2^32 / phi, where phi is the golden ratio ~1.61803).</summary>
    public const uint GoldenRatioFactor32 = 2654435769;
}

/// <summary>Instances of the RefEq for the often used K</summary>
public static class RefEq
{
    /// <summary>RefEq for object, possibly the only thing you need</summary>
    public static readonly RefEq<object> OfObject = default;
}

/// <summary>Uses the `RuntimeHelpers.GetHashCode` and `object.ReferenceEquals`</summary>
public struct RefEq<K> : IEq<K> where K : class
{
    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public K GetTombstone() => null;

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public bool Equals(K x, K y) => ReferenceEquals(x, y);

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public int GetHashCode(K key) => RuntimeHelpers.GetHashCode(key);
}

/// <summary>Uses the `RuntimeHelpers.GetHashCode` and hashes the result with Fibonacci hashing via * GoldenRatio</summary>
public struct GoldenRatioRefEq<K> : IEq<K> where K : class
{
    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public K GetTombstone() => null;

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public bool Equals(K x, K y) => ReferenceEquals(x, y);

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public int GetHashCode(K key) => (int)(RuntimeHelpers.GetHashCode(key) * Eq.GoldenRatioFactor32);
}

/// <summary>Compares via `ReferenceEquals` and gets the hash faster via `RuntimeHelpers.GetHashCode`</summary>
public struct RefEq<A, B> : IEq<(A, B)>
    where A : class
    where B : class
{
    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public (A, B) GetTombstone() => (null, null);

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public bool Equals((A, B) x, (A, B) y) =>
        ReferenceEquals(x.Item1, y.Item1) && ReferenceEquals(x.Item2, y.Item2);

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public int GetHashCode((A, B) key) =>
        Hasher.Combine(RuntimeHelpers.GetHashCode(key.Item1), RuntimeHelpers.GetHashCode(key.Item2));
}

/// <summary>Compares via `ReferenceEquals` and gets the hash faster via `RuntimeHelpers.GetHashCode`</summary>
public struct RefEq<A, B, C> : IEq<(A, B, C)>
    where A : class
    where B : class
    where C : class
{
    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public (A, B, C) GetTombstone() => (null, null, null);

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public bool Equals((A, B, C) x, (A, B, C) y) =>
        ReferenceEquals(x.Item1, y.Item1) && ReferenceEquals(x.Item2, y.Item2) && ReferenceEquals(x.Item3, y.Item3);

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public int GetHashCode((A, B, C) key) =>
        Hasher.Combine(RuntimeHelpers.GetHashCode(key.Item1), Hasher.Combine(RuntimeHelpers.GetHashCode(key.Item2), RuntimeHelpers.GetHashCode(key.Item3)));
}

/// <summary>Add the Use parameter to `Method{T}(..., Use{T} _)` to enable type inference for T,
/// by calling it as `var t = Method(..., Use{T}.It)`</summary>
public readonly struct Pass<A>
{
    public static readonly Pass<A> It = new();
    public readonly A Aval;
}

/// <summary>Add the Pass parameter in type inference for A, B</summary>
public readonly struct Pass<A, B>
{
    public static readonly Pass<A, B> It = new();
    public readonly A Aval;
    public readonly B Bval;
}

/// <summary>Add the Pass parameter in type inference for A, B, C</summary>
public readonly struct Pass<A, B, C>
{
    public static readonly Pass<A, B, C> It = new();
    public readonly A Aval;
    public readonly B Bval;
    public readonly C Cval;
}

/// <summary>Configuration and the tools for the SmallMap and friends</summary>
public static class SmallMap
{
    internal const byte MinFreeCapacityShift = 3; // e.g. for the capacity 16: 16 >> 3 => 2, 12.5% of the free hash slots (it does not mean the entries free slot)
    internal const byte MinHashesCapacityBitShift = 4; // 1 << 4 == 16

    // todo: @wip @remove if not required
    // #if NET7_0_OR_GREATER
    //     internal static Vector128<byte> ByteVec16OfOne = Vector128.Create((byte)1);
    // #endif

    /// <summary>Represent a keyed entry stored in the SmallMap.
    /// Its implementation struct may include the additional Value for the Map or just the Key for the Set.
    /// The implementation may also decide to make Value readonly or writable for the in-place update</summary>
    public interface IEntry<K>
    {
        /// <summary>Returns the key of the payload</summary>
        K Key { get; internal set; }
    }

    /// <summary>Holds a single entry consisting of key and value. 
    /// Value may be set or changed but the key is set in stone (by construction).</summary>
    [DebuggerDisplay("{Key?.ToString()}->{Value}")]
    public struct Entry<K, V> : IEntry<K>
    {
        /// <summary>The readonly key</summary>
        public K Key { get; set; }
        /// <summary>The mutable value</summary>
        public V Value;
        /// <summary>Construct with the key and default value</summary>
        public Entry(K key) => Key = key;
        /// <summary>Construct with the key and value</summary>
        public Entry(K key, V value)
        {
            Key = key;
            Value = value;
        }
    }

    /// <summary>The entry with just a key.
    /// When used with the SmallMap it may represent a Set without wasting the space for the absent value</summary>
    [DebuggerDisplay("{Key?.ToString()}")]
    public struct Entry<K> : IEntry<K>
    {
        /// <summary>The readonly key</summary>
        public K Key { get; set; }
        /// <summary>Construct with the key and default value</summary>
        public Entry(K key) => Key = key;
    }

    /// <summary>Binary representation of the `int`</summary>
    public static string ToB(int x) => System.Convert.ToString(x, 2).PadLeft(32, '0');

    /// <summary>Abstraction to configure your own entries data structure. Check the derived types for the examples</summary>
    public interface IEntries<K, TEntry, TEq>
        where TEntry : struct, IEntry<K>
        where TEq : IEq<K>
    {
        /// <summary>Initializes the entries storage to the specified capacity</summary>
        void Init(int capacityPowerOfTwoPlease);

        /// <summary>Returns the reference to entry by its index, index should map to the present/non-removed entry</summary>
        ref TEntry GetSurePresentEntryRef(int index);

        /// <summary>Adds the key at the "end" of entries - so the order of addition is preserved.</summary>
        ref TEntry AddKeyAndGetEntryRef(K key, int index);
    }

    internal const int MinEntriesCapacity = 2;

    /// <summary>For now to use in the Set as a value</summary>
    public readonly struct NoValue { }

    /// <summary>Stores the entries in a single dynamically reallocated growing array</summary>
    public struct SingleArrayEntries<K, TEntry, TEq> : IEntries<K, TEntry, TEq>
        where TEntry : struct, IEntry<K>
        where TEq : struct, IEq<K>
    {
        internal TEntry[] _entries;

        /// <inheritdoc/>
        public void Init(int capacityPowerOfTwoPlease) =>
            _entries = new TEntry[capacityPowerOfTwoPlease];

        /// <inheritdoc/>
        [MethodImpl((MethodImplOptions)256)]
        public ref TEntry GetSurePresentEntryRef(int index) =>
            ref _entries.GetSurePresentItemRef(index);

        /// <inheritdoc/>
        [MethodImpl((MethodImplOptions)256)]
        public ref TEntry AddKeyAndGetEntryRef(K key, int index)
        {
            if (index == _entries.Length)
                Array.Resize(ref _entries, index << 1);

            ref var e = ref _entries.GetSurePresentItemRef(index);
            e.Key = key;
            return ref e;
        }
    }

    /// <summary>Lookup for the K in the TStackEntries, first by calculating it hash with TEq and searching the hash in the TStackHashes</summary>
    [MethodImpl((MethodImplOptions)256)]
    public static int TryGetStackEntryIndex<K, TEntry, TEq, TCap, TStackHashes, TStackEntries>(
        this ref TStackEntries entries, ref TStackHashes hashes, int count, K key, int hash,
        Pass<TEq, TCap, TEntry> it = default)
        where TEntry : struct, IEntry<K>
        where TEq : struct, IEq<K>
        where TStackHashes : struct, IStack<int, TCap, TStackHashes>
        where TStackEntries : struct, IStack<TEntry, TCap, TStackEntries>
        where TCap : struct, ISize2Plus
    {
        var cap = default(TCap).Size;
        Debug.Assert(count <= cap, $"SmallMap.TryGetStackEntryIndex: count {count} should be <= stack capacity {cap}");
        if (count == 0)
            return -1;

#if NET8_0_OR_GREATER
        if (cap >= 8 & Vector256.IsHardwareAccelerated)
        {
            var vHash = Vector256.Create(hash);
            var vHashes = MemoryMarshal.Cast<int, Vector256<int>>(hashes.AsSpan());
            var i = 0;
            foreach (var vCurr in vHashes)
            {
                var vMatches = Vector256.Equals(vCurr, vHash);
                var matches = Vector256.ExtractMostSignificantBits(vMatches);
                while (matches != 0)
                {
                    var matchIndex = BitOperations.TrailingZeroCount(matches) + i;
                    if (matchIndex >= count) // todo: @perf can I remove this branch?
                        return -1;

                    if (default(TEq).Equals(entries.GetSurePresentItemRef(matchIndex).Key, key))
                        return matchIndex;

                    // Clear lower bits up to and including the first set bit, afaik it can be hw accelerated 
                    // 0b0001_1000 & (0b0001_1000 - 1) -> & 0b0001_1000 & 0b0001_0111 -> 0b0001_0000 
                    matches &= matches - 1;
                }
                if ((i += Vector256<int>.Count) >= count)
                    return -1;
            }
            return -1;
        }
#endif
        for (var i = 0; i < count; ++i)
        {
            var h = hashes.GetSurePresentItemRef(i);
            if (hashes.GetSurePresentItemRef(i) == hash &&
                default(TEq).Equals(entries.GetSurePresentItemRef(i).Key, key))
                return i;
        }
        return -1;
    }

    /// <summary>Adds or updates the entry with the provided value.
    /// Returns `true` if it is updated the existing value.</summary>
    [MethodImpl((MethodImplOptions)256)]
    public static bool AddOrUpdate<TMap, K, V>(this ref TMap map, K key, in V value)
        where TMap : struct, IMap<K, Entry<K, V>>
    {
        map.AddOrGetEntryRef(key, out var found).Value = value;
        return found;
    }

    /// <summary>Lookups for the stored entry by key. Returns the found value or provided default</summary>
    [MethodImpl((MethodImplOptions)256)]
    public static V GetValueOrDefault<TMap, K, V>(this ref TMap map, K key, V defaultValue = default)
        where TMap : struct, IMap<K, Entry<K, V>>
    {
        ref var e = ref map.TryGetEntryRef(key, out var found);
        if (found) return e.Value;
        return defaultValue;
    }
}

/// <summary>Methods to verify the integrity and invariants of SmallMap</summary>
public static class SmallMapDiagnostics
{
    /// <summary>Verifies the integrity and invariants of the SmallMap</summary>
    public static void Verify<TMap, K>(ref this TMap map,
        Action<bool, string> assertCond, IEnumerable<K> expectedKeys = null, Pass<K> pass = default)
        where TMap : struct, IMap<K>, IMapImpl<K>
    {
        map.VerifyHashesAndKeysEq(assertCond, pass);

        map.VerifyProbesRobinHoodInvariants(assertCond, pass);

        map.VerifyKeyHasMetaInfo(assertCond, pass);

        map.VerifyNoDuplicateKeys(assertCond, pass);

        if (expectedKeys != null)
            map.VerifyContainAllKeys(expectedKeys, assertCond, pass);
    }

    /// <summary>Verifies that the hashes correspond to the keys stored in the entries. May be called tests.</summary>
    public static void VerifyHashesAndKeysEq<TMap, K>(ref this TMap map, Action<bool, string> assertCond, Pass<K> _ = default)
        where TMap : struct, IMap<K>, IMapImpl<K>
    {
        var probes = map.Probes;
        var hashes = map.PackedHashesAndIndexes;
        var indexMask = map.Capacity - 1;
        for (var i = 0; i < probes.Length; i++)
        {
            if (probes[i] != 0)
            {
                var h = hashes[i];
                var hashPart = h & ~indexMask;
                var index = h & indexMask;
                var key = map.GetSurePresentKey(index);
                var hashFromKey = map.GetHashCode(key);
                var hashPartFromKey = hashFromKey & ~indexMask;
                assertCond(hashPart == hashPartFromKey, $"Hash mismatch for key:{key}, expected:{hashPartFromKey}, actual:{hashPart}");
            }
        }
    }

    /// <summary>Verifies that there is no duplicate keys stored in hashes -> entries. May be called from the tests.</summary>
    public static void VerifyNoDuplicateKeys<TMap, K>(this TMap map, Action<bool, string> assertCond, Pass<K> _ = default)
        where TMap : struct, IMap<K>, IMapImpl<K>
    {
        var uniq = new Dictionary<K, int>(map.Count);
        var probes = map.Probes;
        var hashes = map.PackedHashesAndIndexes;
        var indexMask = map.Capacity - 1;
        for (var i = 0; i < probes.Length; i++)
        {
            var p = probes[i];
            if (p == 0)
                continue;
            var key = map.GetSurePresentKey(hashes[i] & indexMask);
            if (!uniq.ContainsKey(key))
                uniq.Add(key, 1);
            else
                assertCond(false, $"Duplicate key: {key}");
        }
    }

    /// <summary>Verifies that the probes are consistently increasing</summary>
    public static void VerifyProbesRobinHoodInvariants<TMap, K>(this TMap map, Action<bool, string> assertCond, Pass<K> _ = default)
        where TMap : struct, IMapImpl<K>
    {
        var prevProbe = 0;
        var probes = map.Probes;
        for (var i = 0; i < probes.Length; i++)
        {
            var probe = probes[i];
            var invariant = prevProbe >= probe || prevProbe + 1 == probe;
            assertCond(invariant, $"Probe invariant failed: prevProbe:{prevProbe}, probe:{probe}");
            prevProbe = probe;
        }
    }

    /// <summary>Verifies that each key has a corresponding hash entry which is correctly references this key</summary>
    public static void VerifyKeyHasMetaInfo<TMap, K>(ref this TMap map,
        Action<bool, string> assertCond, Pass<K> _ = default)
        where TMap : struct, IMap<K>
    {
        for (var i = 0; i < map.Count; ++i)
        {
            var key = map.GetSurePresentKey(i);
            var foundIndex = map.TryGetIndex(key);
            assertCond(foundIndex != -1, $"Not found foundIndex:-1 for i:{i}, key:{key}");
            assertCond(foundIndex == i, $"Does not correspond foundIndex:{foundIndex}, i:{i}, key:{key}");
        }
    }

    /// <summary>Verifies that the map contains all passed keys. May be called from the tests.</summary>
    public static void VerifyContainAllKeys<TMap, K>(ref this TMap map,
        IEnumerable<K> expectedKeys, Action<bool, string> assertContains, Pass<K> _ = default)
        where TMap : struct, IMap<K>
    {
        foreach (var key in expectedKeys)
            assertContains(map.ContainsKey(key), $"Key not found: {key}");
    }
}

public interface IMap<K>
{
    /// <summary>Number of entries in the map</summary>
    int Count { get; }
    /// <summary>Lookups for the stored key. Returns its index in the entries or -1</summary>
    int TryGetIndex(K key);
    /// <summary>Lookups for the stored key. If found true, otherwise false</summary>
    bool ContainsKey(K key);
    /// <summary>Lookups for the stored key by the index in the entries data structure</summary>
    K GetSurePresentKey(int index);
}

public interface IMap<K, TEntry> : IMap<K>
    where TEntry : struct, IEntry<K>
{
    /// <summary>Returns the ref to the found entry or the null ref</summary>
    [UnscopedRef]
    ref TEntry TryGetEntryRef(K key, out bool found);

    /// <summary>Returns the ref to the found entry or Adds the entry if not found</summary>
    [UnscopedRef]
    ref TEntry AddOrGetEntryRef(K key, out bool found);

    /// <summary>Adds an entry for sure absent key. Provides the performance in scenarios where you know the key is not yet in the map</summary>
    [UnscopedRef]
    ref TEntry AddSureAbsentDefaultEntryAndGetRef(K key);
}

/// <summary>Implementation details</summary>
public interface IMapImpl<K>
{
    int Capacity { get; }
    byte[] Probes { get; }
    int[] PackedHashesAndIndexes { get; }
    /// <summary>Returns the hash code for the provided key using the IEq implementation used by this map</summary>
    int GetHashCode(K key);
}

/// <summary>
/// Fast and less-allocating hash map without thread safety nets. Please measure it in your own use case before use.
/// It is configurable in regard of hash calculation/equality via `TEq` type parameter and 
/// in regard of key-value storage via `TEntries` type parameter.
/// 
/// Details:
/// - Implemented as a struct so that the empty/default map does not allocate on heap
/// - Hashes and key-values are the separate collections enabling better cash locality and faster performance (data-oriented design)
/// - No SIMD for now to avoid complexity and costs for the smaller maps, so the map is more fit for the smaller sizes.
/// - Provides the "stable" enumeration of the entries in the added order
/// - The TryRemove method removes the hash but replaces the key-value entry with the tombstone key and the default value.
/// For instance, for the `RefEq` the tombstone is <see langword="null"/>. You may redefine it in the `IEq{K}.GetTombstone()` implementation.
/// 
/// </summary>
[DebuggerDisplay("Contains {Count} entries")]
public struct SmallMap<K, TEntry, TEq, TStackCap, TStackHashes, TStackEntries, THeapEntries> : IMap<K, TEntry>, IMapImpl<K>
    where TEntry : struct, IEntry<K>
    where TEq : struct, IEq<K>
    where TStackCap : struct, ISize2Plus
    where TStackHashes : struct, IStack<int, TStackCap, TStackHashes>
    where TStackEntries : struct, IStack<TEntry, TStackCap, TStackEntries>
    where THeapEntries : struct, IEntries<K, TEntry, TEq>
{
#if DEBUG
    // Diagnostic counters to measure the performance of the map operations
    public int PutHashAndIndexWithoutResizing_Count = 0;
    public int PutHashAndIndexWithoutResizing_ProbeGreaterOrEqualCheckCount = 0;
    public int PutHashAndIndexWithoutResizing_ProbeGreaterOrEqualCheckCountAverage =>
        PutHashAndIndexWithoutResizing_Count == 0 ? 0 : PutHashAndIndexWithoutResizing_ProbeGreaterOrEqualCheckCount / PutHashAndIndexWithoutResizing_Count;
    public int PutHashAndIndexWithoutResizing_RobinHoodCount = 0;
    public int PutHashAndIndexWithoutResizing_RobinHoodProbeCheckCount = 0;

    public int LookupCount = 0;
    public int LookupGreaterProbeCheckCount = 0;
    public int LookupGreaterProbeCheckCountAverage => LookupCount == 0 ? 0 : LookupGreaterProbeCheckCount / LookupCount;
    public int LookupEqualProbeCheckCount = 0;
    public int LookupEqualProbeCheckCountAverage => LookupCount == 0 ? 0 : LookupEqualProbeCheckCount / LookupCount;
    public int AddOrGetRefInEntries_Count = 0;
    public int AddOrGetRefInEntries_RobinHoodCount = 0;
    public int AddOrGetRefInEntries_RobinHoodProbeCheckCount = 0;

    public int ResizeProbesAndHashes_Count = 0;
#endif

    internal byte _capacityBitShift;
    // true if the last item in probes and hashes being occupied
    internal bool _isCapacityPaddingFilled;
    internal int _count;

    // todo: @wip update the description, because now we store probes separately from the hashes
    // The _packedHashesAndIndexes elements are of `Int32` with the bits split as following:
    // 00010|000...110|01101
    // |     |         |- The index into the _entries structure, 0-based. The index bit count (indexMask) is the hashes capacity - 1.
    // |     |         | This part of the erased hash is used to get the ideal index into the hashes array, so later this part of hash may be restored from the hash index and its probes.
    // |     |- The remaining middle bits of the original hash
    // |- 5 (MaxProbeBits) high bits of the Probe count, with the minimal value of b00001 indicating the non-empty slot.
    internal byte[] _probes;
    internal int[] _packedHashesAndIndexes;

#pragma warning disable IDE0044 // it tries to make entries readonly but they should stay modify-able to prevent its defensive struct copying
#pragma warning disable CS0649 // field is never assigned to, and will always have its default value
    internal TStackHashes _stackHashes;
    internal TStackEntries _stackEntries;
    internal THeapEntries _heapEntries;
#pragma warning restore CS0649
#pragma warning restore IDE0044

    /// <summary>Capacity bits</summary>
    public int CapacityBitShift => _capacityBitShift;

    /// <summary>Capacity</summary>
    public int Capacity => 1 << _capacityBitShift;

    /// <summary>Mask for the index part of the packedHashAndIndexes entry</summary>
    public int IndexMask => (1 << _capacityBitShift) - 1;

    /// <summary>Access to the probes</summary>
    public byte[] Probes => _probes;

    /// <summary>Access to the hashes and indexes</summary>
    public int[] PackedHashesAndIndexes => _packedHashesAndIndexes;

    /// <inheritdoc />
    public int Count => _count;

    /// <summary>Access to the key-value entries</summary>
    public THeapEntries HeapEntries => _heapEntries;

    /// <summary>Capacity calculates as `1 leftShift capacityBitShift`</summary>
    public SmallMap(byte capacityBitShift)
    {
        // Keep the capacity at least 8 for SIMD Vector256, if you need less space use Stack for that
        _capacityBitShift = capacityBitShift < MinHashesCapacityBitShift ? MinHashesCapacityBitShift : capacityBitShift;
        var capacity = 1 << _capacityBitShift;

        // Extra padding is required to avoid index wrap around for probes and hashes,
        // and ensure that SIMD can read at most 16 bytes starting from the last index.
        // Using either 16 or 1/8 of the capacity, whichever is bigger.
        var tailPadding = 1 << (_capacityBitShift - 3);
        var capacityWithPadding = capacity + (tailPadding > 16 ? tailPadding : 16);

        _probes = new byte[capacityWithPadding];
        _packedHashesAndIndexes = new int[capacityWithPadding];

        _heapEntries.Init(capacity);
    }

    /// <inheritdoc />
    public int GetHashCode(K key) => default(TEq).GetHashCode(key);

    // todo: @perf try using StableGrowingEntries (or Xar) with O(1) random access. And make an default storage for the entries.
    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public K GetSurePresentKey(int index)
    {
        Debug.Assert(index >= 0);
        Debug.Assert(index < _count);
        return index >= _stackEntries.Capacity
            ? _heapEntries.GetSurePresentEntryRef(index - _stackEntries.Capacity).Key
            : _stackEntries.GetSurePresentItemRef(index).Key;
    }

    // todo: @perf try using StableGrowingEntries (or Xar) with O(1) random access. And make an default storage for the entries.
    ///<summary>Get the value ref by the entry index. Also the index corresponds to entry adding order.
    /// Important: it does not check the index bounds, so you need to check that the index is from 0 to map.Count-1</summary>
    [UnscopedRef]
    [MethodImpl((MethodImplOptions)256)]
    public ref TEntry GetSurePresentEntryRef(int index)
    {
        Debug.Assert(index >= 0);
        Debug.Assert(index < _count);
        if (index >= _stackEntries.Capacity)
            return ref _heapEntries.GetSurePresentEntryRef(index - _stackEntries.Capacity);
        return ref _stackEntries.GetSurePresentItemRef(index);
    }

    /// <summary>The actual Lookup implementation in a single place</summary>
    [MethodImpl((MethodImplOptions)256)]
    private int TryGetEntryAndHashIndex(K key, int hash, int indexMask,
        ref int hashIndex, ref byte probe,
#if NET7_0_OR_GREATER
        ref byte probes, ref int hashesAndIndexes
#else
        ref byte[] probes, ref int[] hashesAndIndexes
#endif
    )
    {
#if DEBUG
        ++LookupCount;
#endif
        // Skip over the bigger and equal probes. The hashes with bigger probes overlapping from the earlier ideal positions
        ref var pRef = ref probes.GetSurePresentItemRef(hashIndex);
        while (pRef > probe)
        {
            pRef = ref probes.GetSurePresentItemRef(++hashIndex);
            ++probe;
#if DEBUG
            ++LookupGreaterProbeCheckCount;
#endif
        }

        while (pRef == probe)
        {
            // Compare the hash middle part, then the indexed key
            var h = hashesAndIndexes.GetSurePresentItemRef(hashIndex);
            if ((h & ~indexMask) == (hash & ~indexMask))
                if (default(TEq).Equals(GetSurePresentKey(h & indexMask), key))
                    return h & indexMask;
            pRef = ref probes.GetSurePresentItemRef(++hashIndex);
            ++probe;
#if DEBUG
            ++LookupEqualProbeCheckCount;
#endif
        }
        return -1;
    }

    [UnscopedRef]
    [MethodImpl((MethodImplOptions)256)]
    private ref TEntry AddOrGetRefInEntries(K key, int hash, out bool found)
    {
#if DEBUG
        ++AddOrGetRefInEntries_Count;
#endif
        var indexMask = (1 << _capacityBitShift) - 1;

        // If the free space is less than ~1/8 of capacity (~12.5%) then Resize probes and hashes (but not the entries).
        // Note: this check done here even before lookup and not later at insert, because later we rely on the Lookup hashIndex to do a first insert.
        if (_isCapacityPaddingFilled || indexMask - _count <= (indexMask >>> MinFreeCapacityShift))
            indexMask = ResizeProbesAndHashes(indexMask);

#if NET7_0_OR_GREATER
        ref var probes = ref MemoryMarshal.GetArrayDataReference(_probes);
        ref var hashesAndIndexes = ref MemoryMarshal.GetArrayDataReference(_packedHashesAndIndexes);
#else
        ref var probes = ref _probes;
        ref var hashesAndIndexes = ref _packedHashesAndIndexes;
#endif

        var hashIndex = hash & indexMask;
        byte probe = 1;
        var entryIndex = TryGetEntryAndHashIndex(key, hash, indexMask, ref hashIndex, ref probe, ref probes, ref hashesAndIndexes);
        if (found = entryIndex != -1)
            return ref GetSurePresentEntryRef(entryIndex);

        // We did not find the probe and hash and therefore the key, so insert the new probe and hash
        ref var pRef = ref probes.GetSurePresentItemRef(hashIndex);
        var pRobinHooded = pRef;
        pRef = probe;

        ref var hRef = ref hashesAndIndexes.GetSurePresentItemRef(hashIndex);
        var hRobinHooded = hRef;
        hRef = (hash & ~indexMask) | _count;

        // If the robin hooded probe is empty then we stop
        probe = pRobinHooded;
        while (probe != 0)
        {
            pRef = ref probes.GetSurePresentItemRef(++hashIndex);

            // Otherwise we steal the slot with the smaller probes
            if (pRef < ++probe)
            {
                var pValue = pRef;
                pRef = probe;
                probe = pValue;

                hRef = ref hashesAndIndexes.GetSurePresentItemRef(hashIndex);
                var hValue = hRef;
                hRef = hRobinHooded;
                hRobinHooded = hValue;
#if DEBUG
                ++AddOrGetRefInEntries_RobinHoodCount;
#endif
            }
#if DEBUG
            ++AddOrGetRefInEntries_RobinHoodProbeCheckCount;
#endif
        }

        // @pre - keep the last slot empty so the ResizeProbesAndHashes can rely on it to Stop when scanning the padding span beyond oldCapacity
        _isCapacityPaddingFilled = hashIndex + 2 == _probes.Length;

        return ref _heapEntries.AddKeyAndGetEntryRef(key, _count++ - _stackEntries.Capacity);
    }

    [MethodImpl((MethodImplOptions)256)]
    private void PutHashAndIndexWithoutResizing(int indexMask, int hash, int index)
    {
#if DEBUG
        ++PutHashAndIndexWithoutResizing_Count;
#endif
        var hashIndex = hash & indexMask;
        var hashWithIndex = (hash & ~indexMask) | index;

#if NET7_0_OR_GREATER
        ref var probes = ref MemoryMarshal.GetArrayDataReference(_probes);
        ref var hashesAndIndexes = ref MemoryMarshal.GetArrayDataReference(_packedHashesAndIndexes);
#else
        var probes = _probes;
        var hashesAndIndexes = _packedHashesAndIndexes;
#endif

        // Skip over hashes with the bigger and equal probes. The hashes with bigger probes overlapping from the earlier ideal positions
        byte probe = 1;
        ref var pRef = ref probes.GetSurePresentItemRef(hashIndex);
        while (pRef >= probe)
        {
            ++probe;
            pRef = ref probes.GetSurePresentItemRef(++hashIndex); // no need to wrap around because the probes have the extra capacity
#if DEBUG
            ++PutHashAndIndexWithoutResizing_ProbeGreaterOrEqualCheckCount;
#endif
        }

        // We did not find the hash and therefore the key, so insert the new hash
        var pRobinHooded = pRef;
        pRef = probe;

        ref var hRef = ref hashesAndIndexes.GetSurePresentItemRef(hashIndex);
        var hRobinHooded = hRef;
        hRef = hashWithIndex;

        // If the robin hooded probe is empty then we stop
        probe = pRobinHooded;
        while (probe != 0)
        {
            pRef = ref probes.GetSurePresentItemRef(++hashIndex);

            // Otherwise we steal the slot with the smaller probes
            if (pRef < ++probe)
            {
                var pValue = pRef;
                pRef = probe;
                probe = pValue;

                hRef = ref hashesAndIndexes.GetSurePresentItemRef(hashIndex);
                var hValue = hRef;
                hRef = hRobinHooded;
                hRobinHooded = hValue;
#if DEBUG
                ++PutHashAndIndexWithoutResizing_RobinHoodCount;
#endif
            }
#if DEBUG
            ++PutHashAndIndexWithoutResizing_RobinHoodProbeCheckCount;
#endif
        }

        // @pre - keep the last slot empty so the ResizeProbesAndHashes can rely on it to Stop when scanning the padding span beyond oldCapacity
        _isCapacityPaddingFilled = hashIndex + 2 == _probes.Length;
    }

    /// <inheritdoc />
    [UnscopedRef]
    [MethodImpl((MethodImplOptions)256)]
    public ref TEntry AddOrGetEntryRef(K key, out bool found)
    {
        var hash = default(TEq).GetHashCode(key);

        if (_count > _stackEntries.Capacity)
            return ref AddOrGetRefInEntries(key, hash, out found);

        var i = _stackEntries.TryGetStackEntryIndex(ref _stackHashes, _count, key, hash, Pass<TEq, TStackCap, TEntry>.It);
        if (found = i != -1)
            return ref _stackEntries.GetSurePresentItemRef(i);

        // Add the new entry to the stack if there is still space in the stack
        if (_count < _stackEntries.Capacity)
        {
            var addedIndex = _count++;
            _stackHashes.GetSurePresentItemRef(addedIndex) = hash;
            ref var newStackEntry = ref _stackEntries.GetSurePresentItemRef(addedIndex);
            newStackEntry.Key = key;
            return ref newStackEntry;
        }

        return ref MigrateToHeapAndAddEntry(key, hash);
    }

    private ref TEntry MigrateToHeapAndAddEntry(K key, int hash)
    {
        // Now all capacity of the stack is used.
        // To avoid double work always going linearly through the Stack with the comparison,
        // let's calculate the hash of the keys stored on stack and put them 
        // to the usual HashMap packed hashes and indexes array for the promised O(1) lookup.
        // But the key-value entries will remain on the Stack, and for the found index of the entry we use the GetSurePresentItemRef(index)
        // to get the entry reference either from the Stack or the TEntries.
        // So the entries on stack are guarantied to be stable from the beginning of the map creation, 
        // because they are not copied when the Entries need to Resize (depending on the TEntries implementation). 
        // To ensure stable entries on Entries you need to use 

        var newCapBitShift = Math.Max(_stackEntries.CapacityBitShift + 1, _capacityBitShift);
        _capacityBitShift = (byte)newCapBitShift;

        var newCapacity = 1 << newCapBitShift;
        var newTailPadding = 1 << (newCapBitShift - 3);
        var newCapacityWithPadding = newCapacity + (newTailPadding > 16 ? newTailPadding : 16);
        var indexMask = newCapacity - 1;

        _packedHashesAndIndexes = new int[newCapacityWithPadding];
        _probes = new byte[newCapacityWithPadding];

        var stackCap = _stackEntries.Capacity;
        for (var i = 0; i < stackCap; ++i)
        {
            var h = _stackHashes.GetSurePresentItemRef(i);
            PutHashAndIndexWithoutResizing(indexMask, h, i);
        }

        PutHashAndIndexWithoutResizing(indexMask, hash, stackCap);

        ++_count;
        _heapEntries.Init(stackCap); // Give the heap entries the same initial capacity as Stack, effectively doubling the capacity

        // Set the key for the first entry, which is the 0 index in the entries
        ref var newEntry = ref _heapEntries.GetSurePresentEntryRef(0);
        newEntry.Key = key;
        return ref newEntry;
    }

    /*
    Insertion step by step:

    1. Initially the map is empty. Its capacity mask is 7:
    Index:  0    1    2    3    4    5    6    7
    Hash:  [0]  [0]  [0]  [0]  [0]  [0]  [0]  [0]

    2. Insert the key A with the hash 13, which is 0b0011_0101. 13 & 7 Mask = 5, so the index is 5.
    Index:  0    1    2    3    4    5    6    7
    Hash:  [0]  [0]  [0]  [0]  [0]  [13] [0]  [0]
    Probe:                           1A

    3. Insert the key B with the hash 5, which is 0b0000_1011. 5 & 7 Mask = 5, so the index is again 5.
    Index:  0    1    2    3    4    5    6    7
    Hash:  [0]  [0]  [0]  [0]  [0]  [13] [5]  [0]
    Probe                            1A   2B

    4. Insert the key C with the hash 7, which is 0b0010_0101. 7 & 7 Mask = 7, so the index is 7.
    Index:  0    1    2    3    4    5    6    7
    Hash:  [0]  [0]  [0]  [0]  [0]  [13] [5]  [7]
    Probe:                           1A   2B   1C

    5. Insert the key D with the hash 21, which is 0b0101_0101. 21 & 7 Mask = 5, so the index is again again 5.
    Index:  0    1    2    3    4    5    6    7
    Hash:  [7]  [0]  [0]  [0]  [0]  [13] [5]  [21]
    Probe:  2C                       1A   2B   3D
    */
    [UnscopedRef]
    [MethodImpl((MethodImplOptions)256)]
    private ref TEntry AddSureAbsentDefaultAndGetRefInEntries(K key, int hash)
    {
        // if the free space is less than 1/8 of capacity (12.5%) then Resize
        var indexMask = (1 << _capacityBitShift) - 1;
        if (_isCapacityPaddingFilled || indexMask - _count <= (indexMask >>> MinFreeCapacityShift))
            indexMask = ResizeProbesAndHashes(indexMask);

        PutHashAndIndexWithoutResizing(indexMask, hash, _count);

        return ref _heapEntries.AddKeyAndGetEntryRef(key, (_count++) - _stackEntries.Capacity);
    }

    /// <inheritdoc />
    [UnscopedRef]
    [MethodImpl((MethodImplOptions)256)]
    public ref TEntry AddSureAbsentDefaultEntryAndGetRef(K key)
    {
        var hash = default(TEq).GetHashCode(key);

        if (_count > _stackEntries.Capacity)
            return ref AddSureAbsentDefaultAndGetRefInEntries(key, hash);

        // Add the new entry to the stack if there is still space in stack
        if (_count < _stackEntries.Capacity)
        {
            var newIndex = _count++;
            _stackHashes.GetSurePresentItemRef(newIndex) = hash;
            ref var newStackEntry = ref _stackEntries.GetSurePresentItemRef(newIndex);
            newStackEntry.Key = key;
            return ref newStackEntry;
        }

        return ref MigrateToHeapAndAddEntry(key, hash);
    }

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public int TryGetIndex(K key)
    {
        var hash = default(TEq).GetHashCode(key);
        return _count > _stackEntries.Capacity
            ? TryGetIndexInEntries(key, hash)
            : _stackEntries.TryGetStackEntryIndex(ref _stackHashes, _count, key, hash, Pass<TEq, TStackCap, TEntry>.It);
    }

    /// <inheritdoc />
    public bool ContainsKey(K key) => TryGetIndex(key) != -1;

    [MethodImpl((MethodImplOptions)256)]
    internal int TryGetIndexInEntries(K key, int hash)
    {
#if NET7_0_OR_GREATER
        ref var probes = ref MemoryMarshal.GetArrayDataReference(_probes);
        ref var hashesAndIndexes = ref MemoryMarshal.GetArrayDataReference(_packedHashesAndIndexes);
#else
        var probes = _probes;
        var hashesAndIndexes = _packedHashesAndIndexes;
#endif
        var indexMask = (1 << _capacityBitShift) - 1;
        var hashIndex = hash & indexMask;
        byte probe = 1;
        return TryGetEntryAndHashIndex(key, hash, indexMask, ref hashIndex, ref probe, ref probes, ref hashesAndIndexes);
    }

    /// <inheritdoc />
    [UnscopedRef]
    [MethodImpl((MethodImplOptions)256)]
    public ref TEntry TryGetEntryRef(K key, out bool found)
    {
        var hash = default(TEq).GetHashCode(key);
        if (_count > _stackEntries.Capacity)
        {
            var i = TryGetIndexInEntries(key, hash);
            if (found = i != -1)
                return ref GetSurePresentEntryRef(i); // the index may refer to the stack or heap entries
        }
        else
        {
            var i = _stackEntries.TryGetStackEntryIndex(ref _stackHashes, _count, key, hash, Pass<TEq, TStackCap, TEntry>.It);
            if (found = i != -1)
                return ref _stackEntries.GetSurePresentItemRef(i);
        }
        return ref RefTools<TEntry>.GetNullRef();
    }

    internal int ResizeProbesAndHashes(int indexMask)
    {
#if DEBUG
        ++ResizeProbesAndHashes_Count;
#endif
        var oldCapacity = indexMask + 1;

        var newCapacity = oldCapacity << 1;
        var newIndexMask = (indexMask << 1) | 1;

        var maybeTailPadding = oldCapacity >> 2; // 1/8 of the new capacity
        var newCapacityWithPadding = newCapacity + (maybeTailPadding > 16 ? maybeTailPadding : 16);

        var newProbesArr = new byte[newCapacityWithPadding];
        var newHashesAndIndexes = new int[newCapacityWithPadding];

#if NET7_0_OR_GREATER
        ref var newProbes = ref MemoryMarshal.GetArrayDataReference(newProbesArr);
        ref var newHashes = ref MemoryMarshal.GetArrayDataReference(newHashesAndIndexes);
        ref var oldProbes = ref MemoryMarshal.GetArrayDataReference(_probes);
        ref var oldHashesAndIndexes = ref MemoryMarshal.GetArrayDataReference(_packedHashesAndIndexes);
#else
        var newProbes = newProbesArr;
        var newHashes = newHashesAndIndexes;
        var oldProbes = _probes;
        var oldHashes = _packedHashesAndIndexes;
#endif
        for (var i = 0; i < _probes.Length; ++i)
        {
            var oldProbe = oldProbes.GetSurePresentItem(i);
            if (oldProbe != 0) // for the non-empty probe and therefore hash
            {
                var oldHashAndIndex = oldHashesAndIndexes.GetSurePresentItem(i);

                // First, calculate the ideal hash index for the current probe, it should be in the range of the old capacity/index mask
                var oldHashIndex = i - (oldProbe - 1);
                Debug.Assert(oldHashIndex < oldCapacity, "Old hash index should be less than old capacity");
                var newHashIndex = (oldHashAndIndex & oldCapacity) | oldHashIndex;
                Debug.Assert(newHashIndex == oldHashIndex || newHashIndex == oldHashIndex + oldCapacity, "New hash index should be either the same as old or with the next bit set to the old capacity");

                // No need for robin-hooding because we already did it for the old hashes and now just filling the hashes into the new array which are already in order
                byte probe = 1;
                ref var pRef = ref newProbes.GetSurePresentItemRef(newHashIndex);
                while (pRef != 0)
                {
                    ++probe;
                    pRef = ref newProbes.GetSurePresentItemRef(++newHashIndex);
                }

                pRef = probe;
                newHashes.GetSurePresentItemRef(newHashIndex) = oldHashAndIndex & ~oldCapacity;
            }
            else if (i >= oldCapacity)
                break; // No need to continue scanning the padding, because it is empty and we are done with the old hashes and probes
        }

        ++_capacityBitShift;
        _probes = newProbesArr;
        _packedHashesAndIndexes = newHashesAndIndexes;

#if VERIFY_MAP
        this.VerifyKeyHasMetaInfo(static (x, msg) => Debug.Assert(x, msg), Use<K, TEq>.It);
#endif
        return newIndexMask;
    }
}

